function ProductIdentity(){
 const [lookup,setLookup]=useState<any>(null); const [looking,setLooking]=useState(false); const [asinCheck,setAsinCheck]=useState<any>(null); const [completed,setCompleted]=useState<string[]>([]); const [saved,setSaved]=useState<Record<string,any>>({}); const [saving,setSaving]=useState(false); const [q,setQ]=useState(''); const [status,setStatus]=useState<'all'|'review'|'unmatched'>('all'); const [supplier,setSupplier]=useState('All suppliers'); const [items,setItems]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [selected,setSelected]=useState<any>(null); const [draft,setDraft]=useState({ean:'',asin:'',brand:'',size:''})
 useEffect(()=>{(async()=>{try{const ir=await fetch('/api/product-identity',{cache:'no-store'}),ij=await ir.json();if(ij.ok){const m:Record<string,any>={};(ij.identities||[]).forEach((z:any)=>{m[z.supplier+'-'+z.supplier_offer_id]=z});setSaved(m);setCompleted((ij.identities||[]).filter((z:any)=>z.status==='completed').map((z:any)=>z.supplier+'-'+z.supplier_offer_id))}const slugs=['stateside','sweet-glory','wholesale-sweets','kings-candy'];const rs=await Promise.all(slugs.map(s=>fetch('/api/suppliers/catalogue?supplier='+s,{cache:'no-store'})));const ds=await Promise.all(rs.map(r=>r.json()));setItems(ds.flatMap(d=>d.ok&&Array.isArray(d.offers)?d.offers:[]).map((x:any)=>({...x,identity:x.ean&&x.ean!=='NEEDS MATCH'?'review':'unmatched',asin:x.asin||''}))) }finally{setLoading(false)}})()},[])
 const suppliers=['All suppliers',...Array.from(new Set(items.map(x=>x.supplier||x.source).filter(Boolean)))]
 const filtered=items.filter(x=>!completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))&&(status==='all'||x.identity===status)&&(supplier==='All suppliers'||(x.supplier||x.source)===supplier)&&((x.product||'')+' '+(x.brand||'')+' '+(x.ean||'')+' '+(x.asin||'')).toLowerCase().includes(q.toLowerCase()))
 const open=(x:any)=>{setSelected(x);setLookup(null);setAsinCheck(null);const z=saved[(x.supplier||x.source)+'-'+(x.supplierProductId||x.id)];setDraft({ean:z?.ean||(x.ean&&x.ean!=='NEEDS MATCH'?x.ean:''),asin:z?.asin||x.asin||'',brand:z?.brand||x.brand||'',size:z?.size||x.size||''})}
 function checkAsin(x:any){if(!draft.asin)return;const exact=lookup?.asin&&lookup.asin.toUpperCase()===draft.asin.toUpperCase();const barcode=!!lookup?.checks?.barcode;setAsinCheck({status:exact&&barcode?'HIGH':barcode?'REVIEW':'MANUAL',message:exact&&barcode?'ASIN matches the barcode lookup candidate.':barcode?'Barcode is verified, but this ASIN differs from the lookup candidate. Review the Amazon listing before completing.':'ASIN entered. Verify the Amazon listing against the exact product before completing.'})}
 async function complete(x:any){if(!draft.ean||!draft.asin||!asinCheck)return;setSaving(true);try{const supplier=x.supplier||x.source,offerId=String(x.supplierProductId||x.id);const r=await fetch('/api/product-identity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplier,supplierOfferId:offerId,product:x.product,brand:draft.brand,size:draft.size,ean:draft.ean,asin:draft.asin,status:'completed',eanConfidence:lookup?.confidence||null,asinConfidence:asinCheck.status||null})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Save failed');const key=supplier+'-'+offerId;setSaved(v=>({...v,[key]:d.identity}));setCompleted(v=>v.includes(key)?v:[...v,key]);setSelected(null)}catch(e:any){alert(e?.message||'Unable to save Product Identity')}finally{setSaving(false)}}
 async function barcodeLookup(x:any){if(!draft.ean)return;setLooking(true);setLookup(null);try{const r=await fetch('/api/product-identity/barcode?ean='+encodeURIComponent(draft.ean)+'&title='+encodeURIComponent(x.product||'')+'&brand='+encodeURIComponent(x.brand||'')+'&size='+encodeURIComponent(x.size||''));const d=await r.json();setLookup(d.ok?d.candidate:{error:d.error||'No match found'})}catch{setLookup({error:'Lookup failed'})}finally{setLooking(false)}}
 return <><div className="catalogueHero"><Title k="PRODUCT DATA" t="Product Identity" p="Work through products already pulled from your supplier catalogues. Verify the barcode, add the Amazon ASIN and build a trusted master product record."/><div className="catalogueActions"><span className="identityBadge review">{loading?'LOADING SUPPLIERS…':items.length+' SUPPLIER PRODUCTS'}</span></div></div>
 <div className="catalogueStats"><button className="metric" onClick={()=>setStatus('all')}><span>Supplier products</span><strong>{items.length}</strong><small>waiting in identity workspace</small></button><button className="metric" onClick={()=>setStatus('review')}><span>EAN supplied</span><strong>{items.filter(x=>x.identity==='review').length}</strong><small>verify before confirming</small></button><button className="metric" onClick={()=>setStatus('unmatched')}><span>Missing EAN</span><strong>{items.filter(x=>x.identity==='unmatched').length}</strong><small>barcode needs finding</small></button><button className="metric"><span>ASIN linked</span><strong>{items.filter(x=>x.asin).length}</strong><small>Amazon identities found</small></button></div>
 <section className="catalogueSection"><div className="overviewSectionHead"><div><small>IDENTITY WORK QUEUE</small><h2>Work through supplier products</h2><p>The supplier catalogue stays untouched. Changes here will become Flip Lead's own Product Identity data once persistence is connected.</p></div><div className="catalogueSearch"><select value={supplier} onChange={e=>setSupplier(e.target.value)}>{suppliers.map(s=><option key={s}>{s}</option>)}</select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search product, EAN, ASIN or brand…"/></div></div>
 <div className="catalogueTable"><table><thead><tr><th>Product</th><th>Supplier</th><th>Size</th><th>EAN / UPC</th><th>ASIN</th><th>Identity</th><th></th></tr></thead><tbody>{filtered.map(x=><Fragment key={(x.supplier||x.source)+'-'+x.id}><tr className="identityQueueRow" onClick={()=>selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)?setSelected(null):open(x)}><td><div className="productCell"><b>{x.product}</b><span>{x.brand||'Brand not supplied'}</span></div></td><td>{x.supplier||x.source}</td><td>{x.size||'—'}</td><td>{x.ean&&x.ean!=='NEEDS MATCH'?<b>{x.ean}</b>:<span className="needsMatch">MISSING</span>}</td><td>{x.asin||'—'}</td><td><span className={'identityBadge '+x.identity}>{x.identity==='review'?'REVIEW':'UNMATCHED'}</span></td><td><span className="rowChevron">{selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)?'⌃':'⌄'}</span></td></tr>{selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)&&<tr className="catalogueInlineDetailRow"><td colSpan={7}><div className="identityEditor"><div><small>SUPPLIER RECORD</small><h2>{x.product}</h2><p>{x.supplier||x.source} · {x.rawTitle||x.product}</p></div><div className="identityEditGrid"><label>EAN / UPC<input value={draft.ean} onChange={e=>setDraft({...draft,ean:e.target.value})} placeholder="Enter or paste barcode"/></label><label>Amazon ASIN<input value={draft.asin} onChange={e=>setDraft({...draft,asin:e.target.value.toUpperCase()})} placeholder="e.g. B0XXXXXXXX"/></label><label>Brand<input value={draft.brand} onChange={e=>setDraft({...draft,brand:e.target.value})}/></label><label>Size / weight<input value={draft.size} onChange={e=>setDraft({...draft,size:e.target.value})}/></label></div><div className="identityEditorActions"><button className="secondaryAction" disabled={!draft.ean||looking} onClick={()=>barcodeLookup(x)}>{looking?'Looking up…':'Look up barcode'}</button><button className="secondaryAction" disabled={!draft.asin} onClick={()=>checkAsin(x)}>Check ASIN</button><button className="primary" disabled={!draft.ean||!draft.asin||!asinCheck||saving} onClick={()=>complete(x)}>{saving?'Saving…':'Confirm & Complete'}</button></div>{asinCheck&&<div className={'asinCheck '+asinCheck.status.toLowerCase()}><b>ASIN CHECK · {asinCheck.status}</b><span>{asinCheck.message}</span></div>}{lookup&&<div className="lookupResult">{lookup.error?<b>{lookup.error}</b>:<><div className="lookupResultHead">{lookup.image&&<img src={lookup.image} alt=""/>}<div><small>BARCODE LOOKUP CANDIDATE</small><h3>{lookup.title}</h3><span>{lookup.brand||'Brand unknown'}{lookup.size?' · '+lookup.size:''}</span></div><strong className={'confidence '+lookup.confidence.toLowerCase()}>{lookup.confidence} · {lookup.score}%</strong></div><div className="identityChecks"><span>{lookup.checks.barcode?'✓':'✕'} Barcode</span><span>{lookup.checks.brand?'✓':'○'} Brand</span><span>{lookup.checks.title?'✓':'○'} Product</span><span>{lookup.checks.size?'✓':'○'} Size</span><span>{lookup.asin?'✓ ASIN '+lookup.asin:'○ ASIN not returned'}</span></div>{lookup.asin&&<button className="secondaryAction" onClick={()=>setDraft({...draft,asin:lookup.asin})}>Use ASIN {lookup.asin}</button>}</>}</div>}</div></td></tr>}</Fragment>)}</tbody></table></div>
 {!loading&&!filtered.length&&<div className="identityEmpty"><BookOpen size={24}/><div><b>No products in this view</b><span>Try another supplier or identity filter.</span></div></div>}
 </section></>}

function WholesaleCatalogue(){
 const [supplier,setSupplier]=useState('Stateside Distribution'); const [q,setQ]=useState(''); const [selected,setSelected]=useState<any>(null); const [catalogueFilter,setCatalogueFilter]=useState<'all'|'matched'|'favourites'>('all');
 const openProduct=(x:any)=>{setSelected(s=>s?.id===x.id?null:x)}; const [favourites,setFavourites]=useState<string[]>([])
 const [stateside,setStateside]=useState<any[]>([]); const [sweetGlory,setSweetGlory]=useState<any[]>([]); const [wholesaleSweets,setWholesaleSweets]=useState<any[]>([]); const [kingsCandy,setKingsCandy]=useState<any[]>([]); const [americanCandy,setAmericanCandy]=useState<any[]>([]); const [candyCargo,setCandyCargo]=useState<any[]>([]); const [ycWholesale,setYcWholesale]=useState<any[]>([]); const [worldCandies,setWorldCandies]=useState<any[]>([]); const [americatessen,setAmericatessen]=useState<any[]>([]); const [hancocks,setHancocks]=useState<any[]>([]); const [costSort,setCostSort]=useState<'none'|'caseAsc'|'caseDesc'|'unitAsc'|'unitDesc'>('none'); const [catalogueLoading,setCatalogueLoading]=useState(true); const [syncing,setSyncing]=useState(false); const [syncError,setSyncError]=useState(''); const [syncTimes,setSyncTimes]=useState<Record<string,string>>({})
 useEffect(()=>{try{setFavourites(JSON.parse(localStorage.getItem('flip-lead-favourites')||'[]'))}catch{};(async()=>{try{
  const setters:Record<string,(rows:any[])=>void>={
    'stateside':setStateside,'sweet-glory':setSweetGlory,'wholesale-sweets':setWholesaleSweets,'kings-candy':setKingsCandy,
    'american-candy-n-drinks':setAmericanCandy,'candy-cargo':setCandyCargo,'yc-wholesale':setYcWholesale,
    'world-candies':setWorldCandies,'americatessen':setAmericatessen,'hancocks':setHancocks,
  }
  const specs=CATALOGUE_SUPPLIERS.map(s=>[s.slug,s.name,setters[s.slug]] as const)
  const responses=await Promise.all(specs.map(([slug])=>fetch('/api/suppliers/catalogue?supplier='+slug,{cache:'no-store'})))
  const payloads=await Promise.all(responses.map(r=>r.json()))
  const times:Record<string,string>={}
  payloads.forEach((data:any,i)=>{const [,name,setter]=specs[i];if(data.ok&&Array.isArray(data.offers))setter(data.offers);if(data.lastSync)times[name]=new Date(data.lastSync).toLocaleString('en-GB')})
  setSyncTimes(t=>({...t,...times}))
 }catch{}finally{setCatalogueLoading(false)}})()},[])
 const live=supplier==='Sweet & Glory'?sweetGlory:supplier==='Wholesale Sweets'?wholesaleSweets:supplier==="King's Candy"?kingsCandy:supplier==='American Candy N Drinks'?americanCandy:supplier==='Candy Cargo'?candyCargo:supplier==='Y&C Wholesale'?ycWholesale:supplier==='World Candies'?worldCandies:supplier==='Americatessen'?americatessen:supplier==='Hancocks'?hancocks:stateside; const all=live
 const products=all.filter((x:any)=>{const search=(x.product+' '+(x.brand||'')+' '+(x.size||'')+' '+(x.ean||'')).toLowerCase().includes(q.toLowerCase());const match=x.identityStatus==='completed'||(x.ean&&x.ean!=='NEEDS MATCH');const fav=favourites.includes(x.id);return search&&(catalogueFilter==='all'||(catalogueFilter==='matched'&&match)||(catalogueFilter==='favourites'&&fav))}).sort((a:any,b:any)=>{const fav=Number(favourites.includes(b.id))-Number(favourites.includes(a.id));if(costSort==='none')return fav;const av=costSort.startsWith('case')?Number(a.effectiveCasePrice??a.casePrice):Number(a.effectiveUnitCost??a.unitCost),bv=costSort.startsWith('case')?Number(b.effectiveCasePrice??b.casePrice):Number(b.effectiveUnitCost??b.unitCost);return costSort.endsWith('Asc')?av-bv:bv-av})
 const matched=all.filter((x:any)=>x.ean&&x.ean!=='NEEDS MATCH').length; const toggleFavourite=(id:string)=>{const next=favourites.includes(id)?favourites.filter(x=>x!==id):[...favourites,id];setFavourites(next);localStorage.setItem('flip-lead-favourites',JSON.stringify(next))}
 async function syncSupplier(){setSyncing(true);setSyncError('');try{const isSweet=supplier==='Sweet & Glory';const isWholesaleSweets=supplier==='Wholesale Sweets';const isKings=supplier==="King's Candy";const isAmerican=supplier==='American Candy N Drinks';const isCargo=supplier==='Candy Cargo';const isYC=supplier==='Y&C Wholesale';const isWorld=supplier==='World Candies';const isAmericatessen=supplier==='Americatessen';const isHancocks=supplier==='Hancocks';const r=await fetch(isSweet?'/api/suppliers/sweet-glory':isWholesaleSweets?'/api/suppliers/wholesale-sweets':isKings?'/api/suppliers/kings-candy':isAmerican?'/api/suppliers/american-candy-n-drinks':isCargo?'/api/suppliers/candy-cargo':isYC?'/api/suppliers/yc-wholesale':isWorld?'/api/suppliers/world-candies':isAmericatessen?'/api/suppliers/americatessen':isHancocks?'/api/suppliers/hancocks':'/api/suppliers/stateside',{cache:'no-store'});const raw=await r.text();let d:any;try{d=JSON.parse(raw)}catch{throw new Error(r.ok?'Supplier returned an invalid response':'Supplier sync request failed ('+r.status+'). '+raw.slice(0,120))}if(!r.ok||!d.ok)throw new Error(d.error||'Sync failed');if(!Array.isArray(d.offers)||!d.offers.length)throw new Error('Sync returned no offers — previous catalogue kept');const stamp=new Date().toLocaleString('en-GB');if(isSweet)setSweetGlory(d.offers);else if(isWholesaleSweets)setWholesaleSweets(d.offers);else if(isKings)setKingsCandy(d.offers);else if(isAmerican)setAmericanCandy(d.offers);else if(isCargo)setCandyCargo(d.offers);else if(isYC)setYcWholesale(d.offers);else if(isWorld)setWorldCandies(d.offers);else if(isAmericatessen)setAmericatessen(d.offers);else if(isHancocks)setHancocks(d.offers);else setStateside(d.offers);setSyncTimes({...syncTimes,[supplier]:stamp});setSelected(null)}catch(e:any){setSyncError(e.message||'Unable to sync supplier')}finally{setSyncing(false)}}
 return <><div className="catalogueHero"><Title k="WHOLESALE INTELLIGENCE" t="Supplier Catalogue" p="One product. Many supplier offers. Sync live supplier data, then compare landed cost across wholesalers."/><div className="catalogueActions"><div className="syncAction"><button className="primary" onClick={syncSupplier} disabled={syncing}><Zap size={15}/>{syncing?' Syncing…':' Sync '+supplier}</button><small>{syncTimes[supplier]?'Last synced '+syncTimes[supplier]:'Not synced yet'}</small></div></div></div>
 <div className="catalogueToolbar"><div><small>SUPPLIER</small><select value={supplier} onChange={e=>setSupplier(e.target.value)}><option>Stateside Distribution</option><option>Sweet &amp; Glory</option><option>Wholesale Sweets</option><option>King&apos;s Candy</option><option>American Candy N Drinks</option><option>Candy Cargo</option><option>Y&amp;C Wholesale</option><option>World Candies</option><option>Americatessen</option><option>Hancocks</option></select></div><div><small>CATALOGUE</small><b>All products · In stock</b></div><div><small>CATALOGUE STATUS</small><b>{catalogueLoading?'LOADING…':live.length?'LIVE SYNC · '+live.length+' OFFERS':'NO SAVED OFFERS'}</b></div><div><small>SUPPLIER TERMS</small><b>{supplier==='Sweet & Glory'?'No minimum · stock + expiry supplied':supplier==='Wholesale Sweets'?'Public catalogue · prices VAT inclusive':supplier==="King's Candy"?'Public wholesale catalogue · BBD where supplied':supplier==='World Candies'?'£100 + VAT min · public catalogue · verify displayed VAT basis':supplier==='Y&C Wholesale'?'Trade pricing required · identity catalogue':supplier==='Americatessen'?'No minimum · delivery applies below threshold':supplier==='Hancocks'?'Trade wholesale · public case pricing':'Prices ex VAT · £50 min · £300 free mainland delivery'}</b></div></div>
 {syncError&&<div className="syncError"><AlertCircle size={15}/><div><b>Supplier sync could not complete</b><span>{syncError}. Existing verified records have been kept.</span></div></div>}
 <div className="catalogueStats"><button className="metric" onClick={()=>setCatalogueFilter('all')}><span>In-stock offers</span><strong>{catalogueLoading?'—':all.length}</strong><small>{catalogueLoading?'loading saved catalogue':'saved supplier catalogue'}</small></button><button className="metric" onClick={()=>setCatalogueFilter('matched')}><span>EAN matched</span><strong>{catalogueLoading?'—':matched}</strong><small>{catalogueLoading?'loading identities':(all.length-matched)+' need barcode match'}</small></button><button className="metric" onClick={()=>setCatalogueFilter('favourites')}><span>Favourites</span><strong>{catalogueLoading?'—':all.filter((x:any)=>favourites.includes(x.id)).length}</strong><small>products you buy often</small></button><button className="metric" onClick={()=>setCatalogueFilter('all')}><span>Supplier offers</span><strong>{catalogueLoading?'—':all.length}</strong><small>{supplier}</small></button></div>
 <section className="catalogueSection"><div className="overviewSectionHead"><div><small>{supplier.toUpperCase()} · ALL IN-STOCK</small><h2>Product catalogue</h2><p>{syncTimes[supplier]?'Last synced '+syncTimes[supplier]:'Run Sync to load the live supplier catalogue.'}</p></div><div className="catalogueSearch"><select value={costSort} onChange={e=>setCostSort(e.target.value as any)}><option value="none">Default order</option><option value="caseAsc">Case cost · low to high</option><option value="caseDesc">Case cost · high to low</option><option value="unitAsc">Unit cost · low to high</option><option value="unitDesc">Unit cost · high to low</option></select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search product, EAN, brand or size…"/></div></div>
 <div className="catalogueTable"><table><thead><tr><th>★</th><th>Product</th><th>Identity</th><th>EAN / UPC</th><th>Case</th><th>Case cost</th><th>Unit cost</th><th>Source</th><th>Availability</th><th>Details</th></tr></thead><tbody>{products.map((x:any)=><Fragment key={x.id}><tr onClick={()=>openProduct(x)} className={selected?.id===x.id?'selected':''}><td><button className="supplierMore" title="Favourite" onClick={e=>{e.stopPropagation();toggleFavourite(x.id)}}><Star size={15} fill={favourites.includes(x.id)?'currentColor':'none'}/></button></td><td><div className="productCell"><b>{x.product}</b><span>{x.brand||'Brand not supplied'}{x.size?' · '+x.size:''}</span><small>{x.rawTitle&&x.rawTitle!==x.product?'Supplier listing: '+x.rawTitle:'Stateside catalogue offer'}</small></div></td><td>{x.identityStatus==='completed'?<span className="identityBadge confirmed">CONFIRMED</span>:x.ean&&x.ean!=='NEEDS MATCH'?<span className="identityBadge review">EAN SUPPLIED</span>:<span className="identityBadge unmatched">UNMATCHED</span>}</td><td>{x.ean&&x.ean!=='NEEDS MATCH'?<b>{x.ean}</b>:<span className="needsMatch">NEEDS MATCH</span>}</td><td>{x.caseQty} × {x.size||'unit'}</td><td><b>{gbp(x.effectiveCasePrice??x.casePrice)}</b><small>{x.priceBasis==='EX VAT'?gbp(x.casePrice)+' ex VAT · effective inc VAT':'supplier price'}</small></td><td><b>{gbp(x.effectiveUnitCost??x.unitCost??x.casePrice/x.caseQty)}</b><small>{x.priceBasis==='EX VAT'?'effective inc VAT':'calculated'}</small></td><td><small>{supplier==='Sweet & Glory'?(x.expiry||x.source):x.source}</small></td><td><span className="stockPill">{x.stockQty?x.stockQty+' IN STOCK':x.status}</span></td><td><button className="supplierMore" onClick={e=>{e.stopPropagation();openProduct(x)}}>View</button></td></tr>{selected?.id===x.id&&<tr className="catalogueInlineDetailRow"><td colSpan={10}>{selected&&<section className="catalogueDetail"><div className="catalogueDetailHead"><div><small>MASTER PRODUCT + SUPPLIER OFFER</small><h2>{x.product} <span>{x.size}</span></h2><p>{x.brand||'Brand not supplied'}</p></div><button className="reset" onClick={e=>{e.stopPropagation();setSelected(null)}}>Close</button></div><div className="identityPanel"><div className="identityPanelHead"><div><small>PRODUCT IDENTITY</small><b>{x.identityStatus==='completed'?'Verified identity':x.ean&&x.ean!=='NEEDS MATCH'?'Supplier EAN supplied · review required':'Identity needs matching'}</b></div>{x.identityStatus==='completed'?<span className="identityBadge confirmed">VERIFIED</span>:x.ean&&x.ean!=='NEEDS MATCH'?<span className="identityBadge review">EAN SUPPLIED</span>:<span className="identityBadge unmatched">UNMATCHED</span>}</div><div className="identityChecks"><span>{x.ean&&x.ean!=='NEEDS MATCH'?'✓':'○'} EAN / UPC {x.ean&&x.ean!=='NEEDS MATCH'?'supplied':'needed'}</span><span>{x.brand?'✓':'○'} Brand {x.brand?'supplied':'not supplied'}</span><span>✓ Product name supplied</span><span>{x.size?'✓':'○'} Size {x.size?'supplied':'needs review'}</span><span>○ Amazon ASIN not linked</span></div><p>Flip Lead will only link supplier and Amazon listings when the product identity agrees. Ambiguous barcode, brand, variant, size or pack matches must be reviewed rather than silently merged.</p></div><div className="offerGrid"><Fact l="EAN / UPC" v={x.ean&&x.ean!=='NEEDS MATCH'?x.ean:'NEEDS MATCH'}/><Fact l="Supplier" v={x.supplier||x.source}/><Fact l="Supplier SKU" v={x.supplierSku||'Not supplied'}/><Fact l="Case quantity" v={String(x.caseQty)}/><Fact l="Case cost" v={gbp(x.effectiveCasePrice??x.casePrice)+(x.priceBasis==='EX VAT'?' inc VAT':'')}/><Fact l="Unit cost" v={gbp(x.effectiveUnitCost??x.unitCost??x.casePrice/x.caseQty)}/><Fact l="Availability" v={x.status}/><Fact l="Last checked" v={x.checked?new Date(x.checked).toLocaleString('en-GB'):'26 Sep 2026'}/></div><div className="matchEmpty"><div><b>Supplier Match</b><span>No competing supplier offers matched yet. Supplier #2 will compare unit cost, landed cost, MOQ, delivery and expiry against this exact product.</span></div><a href={x.url} target="_blank" rel="noreferrer">Open source product ↗</a></div></section>}</td></tr>}</Fragment>)}</tbody></table></div>
 <div className="catalogueFoot"><span>{catalogueLoading?'LOADING SUPPLIER DATA':live.length?'LIVE SUPPLIER DATA':'NO SAVED SUPPLIER DATA'}</span><p>Supplier data is retained with source and sync time. Prices and availability can change; refresh before an order is placed.</p></div></section>
 
 <div className="catalogueNext"><BookOpen size={18}/><div><b>Cross-supplier architecture ready.</b><span>EAN/UPC is the primary match key. Name + brand + exact size may suggest matches, but Flip Lead will not silently merge uncertain products.</span></div></div></>}

